args<-commandArgs(FALSE);f<-grep('^--file=',args,value=TRUE)
if(length(f))setwd(dirname(normalizePath(sub('^--file=','',f[1]))))
Sys.setlocale('LC_COLLATE','C')
for(d in c('results/quality_control','results/plot_data','figures'))dir.create(d,recursive=TRUE,showWarnings=FALSE)
for(z in c('OVCAR5','OVCAR8','ID8'))for(d in c('differential_expression','normalized_counts','pathway_enrichment'))dir.create(file.path('results',d,z),recursive=TRUE,showWarnings=FALSE)
steps <- c('01_data_preprocessing.R','02_differential_expression_DESeq2.R','03_transcriptomic_PCA.R','04_gene_set_enrichment_GSEA.R','05_SREBP1_lipogenic_analysis.R','06_generate_transcriptomic_figures.R')
stopifnot(all(file.exists(file.path('scripts', steps))))
for(s in file.path('scripts',steps)){message('RUN ',s);source(s)}
writeLines(capture.output(sessionInfo()),'results/quality_control/sessionInfo.txt')
p<-installed.packages();write.table(p[,c('Package','Version')],'results/quality_control/package_versions.txt',sep='\t',quote=FALSE,row.names=FALSE)